/// Every move's clip, indexed by `move_clip(class, kind)`.
pub static MOVE_CLIPS: &[&[Pose]] = &[
    &MOVE_BULWARK_BASH,
    &MOVE_BULWARK_SLAM,
    &MOVE_BULWARK_GRAPPLE,
    &MOVE_CHAMPION_SWEEP,
    &MOVE_CHAMPION_DRIVE,
    &MOVE_CHAMPION_UPPERCUT,
    &MOVE_SHADOW_REAVER_SLASH,
    &MOVE_SHADOW_REAVER_EXECUTIONER,
    &MOVE_SHADOW_REAVER_GUILLOTINE,
    &MOVE_ELEMENTALIST_BOLT,
    &MOVE_ELEMENTALIST_FISSURE,
    &MOVE_ELEMENTALIST_FIRE_PILLAR,
    &MOVE_BLOOD_MAGE_REND,
    &MOVE_BLOOD_MAGE_BLACK_SPIKE,
    &MOVE_BLOOD_MAGE_REAPER_S_DEBT,
    &MOVE_DUAL_MAGE_STEP_STRIKE,
    &MOVE_DUAL_MAGE_LANCE,
    &MOVE_DUAL_MAGE_JUDGEMENT,
];

/// Which clip a move plays.
///
/// Generated alongside the clips themselves, so a move added to
/// `sim::moves` cannot end up without one.
pub const fn move_clip(class: usize, kind: usize) -> usize {
    match (class, kind) {
        (0, 0) => 0,  // move_bulwark_bash
        (0, 1) => 1,  // move_bulwark_slam
        (0, 2) => 2,  // move_bulwark_grapple
        (1, 0) => 3,  // move_champion_sweep
        (1, 1) => 4,  // move_champion_drive
        (1, 2) => 5,  // move_champion_uppercut
        (2, 0) => 6,  // move_shadow_reaver_slash
        (2, 1) => 7,  // move_shadow_reaver_executioner
        (2, 2) => 8,  // move_shadow_reaver_guillotine
        (3, 0) => 9,  // move_elementalist_bolt
        (3, 1) => 10, // move_elementalist_fissure
        (3, 2) => 11, // move_elementalist_fire_pillar
        (4, 0) => 12, // move_blood_mage_rend
        (4, 1) => 13, // move_blood_mage_black_spike
        (4, 2) => 14, // move_blood_mage_reaper_s_debt
        (5, 0) => 15, // move_dual_mage_step_strike
        (5, 1) => 16, // move_dual_mage_lance
        (5, 2) => 17, // move_dual_mage_judgement
        _ => 0,
    }
}
